def add_field(p,code):
 f=OxmlElement('w:fldSimple');f.set(qn('w:instr'),code);p._p.append(f)
d=Document(root/'系统的使用文档.docx')
body=d._element.body
for e in list(body):
 if e.tag!=qn('w:sectPr'):body.remove(e)
for style in d.styles:
 for border in list(style._element.findall('.//'+qn('w:pBdr'))):border.getparent().remove(border)
d.styles['Caption'].font.color.rgb=RGBColor(0,0,0)
normal=d.styles['Normal'];normal.font.size=Pt(10.5);normal.font.bold=False;normal.paragraph_format.line_spacing=1.12;normal.paragraph_format.space_after=Pt(5)
for name,size in [('Title',26),('Heading 1',16),('Heading 2',11.5)]:
 s=d.styles[name];s.font.size=Pt(size);s.font.color.rgb=RGBColor(0,0,0);s.paragraph_format.space_before=Pt(7);s.paragraph_format.space_after=Pt(6)
for sec in d.sections:
 sec.top_margin=Cm(1.8);sec.bottom_margin=Cm(1.7)
 p=sec.header.paragraphs[0];p.text='灵兔洞察系统    用户图文教程';p.runs[0].font.size=Pt(9);p.runs[0].font.color.rgb=RGBColor(0,0,0)
